fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut low = 0usize;
    let mut high = v.len() - 1;

    // Invariant: target k is within v[low..=high]
    while low < high {
        let mid = low + (high - low) / 2;
        if v[mid] < k {
            low = mid + 1;
        } else {
            high = mid; // target must be at or before mid
        }
    }

    // low == high, and v[low] == k guaranteed by assumptions
    low
}